import{_ as o,o as l,c,a2 as t}from"./chunks/framework.BUwdTBzS.js";const h=JSON.parse('{"title":"开发规范-红线","description":"","frontmatter":{"title":"开发规范-红线"},"headers":[],"relativePath":"rules/开发规范-红线.md","filePath":"rules/开发规范-红线.md","lastUpdated":null}'),d={name:"rules/开发规范-红线.md"};function i(a,e,r,s,n,u){return l(),c("div",null,[...e[0]||(e[0]=[t('<blockquote><p>📄 本页由源文件 <code>rules/开发规范-红线.mdc</code> 自动投影生成（单一权威源）。请勿直接编辑本页。</p></blockquote><h1 id="开发规范-红线" tabindex="-1">开发规范-红线 <a class="header-anchor" href="#开发规范-红线" aria-label="Permalink to &quot;开发规范-红线&quot;">​</a></h1><p>&lt;!-- 📌 本文件定位：alwaysApply 红线规范，每次对话都会加载，直接消耗上下文窗口。 ⚠️ 准入标准：①违反即出事的硬性禁令 ②每次编码都必须遵守的底线 ③1-3行能说清 🎯 目标：≤80行，只留&quot;不看会出问题&quot;的内容。参考信息已迁移到 dev-flow Skill。 --&gt;</p><p>本规则为最高优先级红线。详细规范通过 <code>dev-flow</code> skill 按需加载。</p><hr><h2 id="操作红线" tabindex="-1">操作红线 <a class="header-anchor" href="#操作红线" aria-label="Permalink to &quot;操作红线&quot;">​</a></h2><ul><li>严禁擅自 <code>git commit</code>/<code>git push</code>/修改 <code>.git</code> 配置（commit 只能生成信息）</li><li>严禁在公共/共享分支上直接提交代码；误操作后须按场景用 stash/cherry-pick 搬移改动，禁止 merge 公共分支（详见 <code>skills/dev-flow/references/shared-rules.md</code> §7.1）</li><li>严禁删除重要文件、修改项目配置（除非用户要求）、主动创建文档文件</li><li>Commit 格式：<code>&lt;type&gt;: &lt;description&gt;</code>（无 scope，不加括号）</li><li>新增代码质量底线：发现老代码缺陷必须在新代码中修正，禁止延续缺陷</li></ul><h2 id="核心原则-12-条红线" tabindex="-1">核心原则（12 条红线） <a class="header-anchor" href="#核心原则-12-条红线" aria-label="Permalink to &quot;核心原则（12 条红线）&quot;">​</a></h2><ol><li><strong>需求理解优先</strong>——禁止猜测，不确定点汇总确认，99% 把握再执行</li><li><strong>最小入侵</strong>——保持原有逻辑，只追加必要新逻辑；禁止为单次使用的代码做抽象，禁止添加未被要求的灵活性/可配置性；发现无关缺陷/死代码→提及但不擅自修改；自己的改动导致的孤儿导入/变量/函数→主动清理；自检：每行变更必须可追溯到用户请求</li><li><strong>兼容性优先</strong>——不确定时主动查询 MDN/Can I Use</li><li><strong>根因定位与验证闭环</strong>——禁止盲改；先定位根因再修复；改完必须验证</li><li><strong>安全底线</strong>——禁止拼接 SQL/HTML，禁止硬编码密钥/token</li><li><strong>副作用必须清理</strong>——useEffect 必须 cleanup；卸载后禁止 setState</li><li><strong>边界条件与防御性编码</strong>——处理空值/undefined/空数组/异常输入；所有链式属性访问必须使用可选链 <code>?.</code>（如 <code>response?.data?.items?.length</code>），禁止裸链式访问；无论值来源（props/state/回调参数/守卫后分支），均无例外；增量更新时优先优化本次改动行涉及的链式调用，同函数内的其他链式调用建议一并优化</li><li><strong>异步与竞态安全</strong>——并发请求处理竞态；异步有 loading/error/success 三态；useEffect 中异步操作必须处理组件卸载场景（cleanup 取消/忽略结果）</li><li><strong>错误处理</strong>——禁止空 catch 吞异常；组件树用 Error Boundary 兜底</li><li><strong>先搜索后编码</strong>——新增工具函数/组件/Hook 前必须先搜索项目已有实现并确认可直接使用，有则复用（不改造原代码），无则再新建</li><li><strong>主动思考更优方案</strong>——执行时必须思考是否有更好实现；发现更优方案及时建议；禁止机械执行</li><li><strong>上下文管理</strong>——不相关任务开新对话；长对话用 TODO 持久化；遗忘时重读 working-context</li></ol><h2 id="前端编码底线-每次写代码必须遵守" tabindex="-1">前端编码底线（每次写代码必须遵守） <a class="header-anchor" href="#前端编码底线-每次写代码必须遵守" aria-label="Permalink to &quot;前端编码底线（每次写代码必须遵守）&quot;">​</a></h2><h3 id="typescript-javascript" tabindex="-1">TypeScript / JavaScript <a class="header-anchor" href="#typescript-javascript" aria-label="Permalink to &quot;TypeScript / JavaScript&quot;">​</a></h3><ul><li><code>const</code> 优先，需重新赋值用 <code>let</code>，禁止 <code>var</code></li><li>严格全等 <code>===</code> / <code>!==</code>，禁止 <code>==</code> / <code>!=</code></li><li>禁止 <code>any</code>，用 <code>unknown</code> + 类型守卫；接口返回值必须定义明确类型</li><li>解构优先：<code>const { name, age } = user</code>，禁止反复 <code>user.name</code></li><li>字符串用模板字面量，禁止 <code>+</code> 拼接</li><li>数组操作返回新实例（<code>map</code>/<code>filter</code>/展开），禁止原地 <code>push</code>/<code>splice</code> 修改源数组（纯函数场景）</li><li><strong>禁止嵌套三元表达式</strong>：≥2 层三元嵌套必须拆分为 <code>if</code> 早返回或独立变量；单层三元仅在逻辑极简时允许（如 <code>x ? A : B</code>）</li><li><strong>分号前禁止空格</strong>：<code>290;</code> 正确，<code>290 ;</code> 错误（违反 <code>semi-spacing</code> 规则）</li><li><strong>复杂参数/条件必须提取为命名变量</strong>：函数调用中的多行三元表达式、多分支条件对象必须提取为独立的命名变量（如 <code>externalParam</code> / <code>orgParam</code>），禁止内联在函数参数中；多函数共用的对象构造逻辑必须抽取为公共工厂函数</li></ul><h3 id="react" tabindex="-1">React <a class="header-anchor" href="#react" aria-label="Permalink to &quot;React&quot;">​</a></h3><ul><li>组件用函数式 + Hooks，禁止新增 class 组件</li><li><code>useEffect</code> 必须 cleanup（定时器/订阅/事件监听）；依赖数组禁止盲加，先分析变量会不会变</li><li>状态更新依赖前值时用函数式：<code>setState(prev =&gt; prev + 1)</code></li><li>避免不必要的重渲染：合理使用 <code>React.memo</code> / <code>useMemo</code> / <code>useCallback</code></li><li>JSX 布尔属性用花括号：<code>bordered={false}</code>，禁止 <code>bordered=&quot;false&quot;</code></li><li><strong>JSX 内禁止复杂表达式</strong>：JSX props 中的条件逻辑超过单层三元时，必须提取为 <code>useMemo</code> 变量或组件顶部的 <code>const</code>；<code>useState</code> 初始值含条件逻辑时用惰性初始化 <code>useState(() =&gt; { ... })</code></li><li><strong>useEffect 内多分支重复逻辑必须提取</strong>：多个条件分支中重复的 <code>setState</code>/<code>ref 赋值</code>/回调调用必须提取到分支外统一执行；差异部分用变量（如 <code>expandId</code>）承接，公共部分在分支后一次性处理</li><li><strong>异步 try-catch 用 <code>finally</code> 统一清理状态</strong>：<code>setLoading(false)</code> 等清理操作禁止在 try 和 catch 中各写一份，必须用 <code>finally</code> 统一处理</li></ul><h3 id="css-scss" tabindex="-1">CSS / SCSS <a class="header-anchor" href="#css-scss" aria-label="Permalink to &quot;CSS / SCSS&quot;">​</a></h3><ul><li>缩进 2 空格；选择器后必须有空格（<code>.class {</code> 非 <code>.class{</code>）</li><li>禁止 <code>!important</code>（除非覆盖第三方 JS 内联样式且无组件 API 可用）</li><li>嵌套不超过 3 层；禁止用标签选择器（<code>div</code>/<code>span</code>）做业务样式</li><li>颜色/间距/字号优先使用项目 CSS 变量（<code>var()</code>），禁止硬编码魔法值</li></ul><h3 id="依赖管理" tabindex="-1">依赖管理 <a class="header-anchor" href="#依赖管理" aria-label="Permalink to &quot;依赖管理&quot;">​</a></h3><ul><li>安装依赖前先检查 lock 文件现有版本，禁止盲目升级</li><li>禁止修改 lock 文件格式版本（如 lockfileVersion）</li><li>新增依赖必须说明用途，优先选已在项目中使用的包</li><li>💡 版本映射表、安装检查清单、恢复方法等详细操作 → 按需规则 <code>依赖管理与Lock文件规范</code></li></ul><h3 id="编码完成必检-每次编码后强制执行-含迭代修复" tabindex="-1">编码完成必检（每次编码后强制执行，含迭代修复） <a class="header-anchor" href="#编码完成必检-每次编码后强制执行-含迭代修复" aria-label="Permalink to &quot;编码完成必检（每次编码后强制执行，含迭代修复）&quot;">​</a></h3><ul><li><strong>步骤 5.5 不可跳过</strong>：dev-flow 中每轮编码（含迭代修复、步骤 5 内部多轮修复）完成后，必须执行步骤 5.5（5.5a L1 审查 + 5.5b 文档同步 + 5.5c ESLint 自检），不得跳过直接向用户汇报完成；用户主动要求&quot;生成 commit&quot;或&quot;代码审查&quot;时，若 5.5 未执行，必须先补执行 5.5 再继续</li><li><strong>L1 审查 = 完整 8 项检查</strong>：ESLint 命令行、可选链、浏览器兼容性、React 规范、CSS 规范、异步竞态、边界条件、通用检查（调试代码/未使用 import）</li><li><strong><code>read_lints</code> ≠ ESLint</strong>：IDE 的 <code>read_lints</code> 只检查 TypeScript 类型错误，不覆盖 ESLint 规则（如 <code>import/no-duplicates</code>、<code>arrow-parens</code>、<code>max-len</code>、<code>no-param-reassign</code>）；两者都必须执行</li><li><strong>迭代修复不豁免</strong>：无论是首次开发还是第 N 轮迭代修复，每轮编码完成后都必须执行 L1 审查，不因&quot;改动小&quot;而跳过</li></ul><h2 id="无-dev-flow-直接改代码-精要" tabindex="-1">无 dev-flow 直接改代码（精要） <a class="header-anchor" href="#无-dev-flow-直接改代码-精要" aria-label="Permalink to &quot;无 dev-flow 直接改代码（精要）&quot;">​</a></h2><ul><li>仍守本文件 12 条核心红线 + 前端编码底线</li><li>必跑 <code>read_lints</code> + 改动行 ESLint，不得自动 commit</li><li>改动 ≥4 文件 / ≥30 行 / 涉及核心模块 → 主动建议改用 <code>dev-flow</code> 命令</li><li>详细规则 → <code>skills/dev-flow/references/no-dev-flow-mode.md</code></li></ul>',22)])])}const p=o(d,[["render",i]]);export{h as __pageData,p as default};
